import "server-only";

import path from "node:path";

import { migrate } from "drizzle-orm/node-postgres/migrator";

import { getDb } from "./client.ts";

// Applies the SQL migrations in drizzle/ (generated by `pnpm db:generate`, committed) once per
// process, on first use: locally, in scripts and in production (the Dockerfile copies drizzle/).
// Migrations are additive only, so an older image still works after a rollback.

const MIGRATIONS_FOLDER = path.join(process.cwd(), "drizzle");

let ready: Promise<void> | undefined;

/** Brings the database schema up to date. A failure is retried on the next call. */
export function ensureDatabase(): Promise<void> {
  ready ??= migrate(getDb(), { migrationsFolder: MIGRATIONS_FOLDER }).catch((err: unknown) => {
    ready = undefined;
    throw err;
  });
  return ready;
}
